function Status({ status }) {
  if (status === 'batal') return <p>Pesanan dibatalkan.</p>;
  let pesan = 'Pesanan sedang dikemas';
  if (status === 'dikirim') pesan = 'Pesanan dalam perjalanan';
  return <p>{pesan}</p>;
}

export default function App() {
  return <Status status="dikirim" />;
}

